svg.script:
//
    (function() {
      var root = document.getElementById('a12p2b-svg-root');
      if (!root) return;

      var btn1 = document.getElementById('a12p2b-btn-step1');
      var btn2 = document.getElementById('a12p2b-btn-step2');
      var btn3 = document.getElementById('a12p2b-btn-step3');

      var info1 = document.getElementById('a12p2b-info-step1');
      var info2 = document.getElementById('a12p2b-info-step2');
      var info3 = document.getElementById('a12p2b-info-step3');

      function setStep(step) {
        root.setAttribute('data-step', step);

        if (info1) info1.style.display = (step === '1') ? 'block' : 'none';
        if (info2) info2.style.display = (step === '2') ? 'block' : 'none';
        if (info3) info3.style.display = (step === '3') ? 'block' : 'none';
      }

      function attachHandler(el, step) {
        if (!el) return;
        el.addEventListener('click', function() { setStep(step); });
        el.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
            e.preventDefault();
            setStep(step);
          }
        });
      }

      attachHandler(btn1, '1');
      attachHandler(btn2, '2');
      attachHandler(btn3, '3');

      // Suporte Global a Atalhos de Teclado (1, 2, 3)
      window.addEventListener('keydown', function(e) {
        if (e.key === '1') setStep('1');
        if (e.key === '2') setStep('2');
        if (e.key === '3') setStep('3');
      });
    })();
  //
